#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static unsigned long long mulmod(unsigned long long a, unsigned long long b, unsigned long long mod) {
    __uint128_t res = ( __uint128_t ) a * b;
    return (unsigned long long)(res % mod);
}

static unsigned long long powmod(unsigned long long base, unsigned long long exp, unsigned long long mod) {
    unsigned long long result = 1 % mod;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mulmod(result, base, mod);
        base = mulmod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

static int is_prime_ull(unsigned long long n) {
    if (n < 2) return 0;
    static const unsigned long long bases[] = {2, 3, 5, 7, 11, 13};
    // small prime check
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        if (n == bases[i]) return 1;
        if (n % bases[i] == 0) return 0;
    }
    // write n-1 as d*2^s with d odd
    unsigned long long d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        unsigned long long a = bases[i] % n;
        if (a == 0) continue; // base divides n, already handled above
        unsigned long long x = powmod(a, d, n);
        if (x == 1 || x == n-1) continue;
        int composite = 1;
        for (unsigned int r = 1; r < s; ++r) {
            x = mulmod(x, x, n);
            if (x == n-1) { composite = 0; break; }
        }
        if (composite) return 0;
    }
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    unsigned long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Upper bound used by the original program (0xBFA17DC6)
    if (n > 0xBFA17DC6ULL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (is_prime_ull(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");
    return 0;
}
